const allItems = $input.all();

// Emails (from Gmail — have threadId)
const emails = allItems
  .filter(item => item.json.threadId)
  .map(item => ({
    from: item.json.From || item.json.from || 'Unknown',
    subject: item.json.Subject || item.json.subject || 'No Subject',
    snippet: (item.json.snippet || item.json.textPlain || 'No preview').substring(0, 120)
  }));

// News items (from RSS — have title + link, no threadId)
const newsItems = allItems
  .filter(item => item.json.title && item.json.link && !item.json.threadId)
  .slice(0, 15)
  .map(item => ({
    title: (item.json.title || '').replace(/<[^>]*>/g, ''),
    link: item.json.link || '',
    pubDate: item.json.pubDate || item.json.isoDate || ''
  }));

// Calendar events (have summary or start.dateTime)
const events = allItems
  .filter(item => {
    const j = item.json;
    return (j.summary || j.start?.dateTime || j.start?.date) && !j.threadId && !j.link;
  })
  .map(item => {
    const j = item.json;
    let startTime = '';
    let endTime = '';
    if (j.start?.dateTime) {
      startTime = new Date(j.start.dateTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true });
      endTime = j.end?.dateTime ? new Date(j.end.dateTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true }) : '';
    } else if (j.start?.date) {
      startTime = 'All day';
    }
    return {
      title: j.summary || 'Untitled Event',
      start: startTime,
      end: endTime,
      location: j.location || ''
    };
  });

return [{
  json: {
    date: new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
    emailCount: emails.length,
    emails: JSON.stringify(emails),
    newsCount: newsItems.length,
    news: JSON.stringify(newsItems),
    eventCount: events.length,
    events: JSON.stringify(events)
  }
}];

