=Here are today's news headlines. Write a 1-line summary (max 15 words) for each headline. Return ONLY a JSON array of objects with "title" and "summary" keys. No markdown, no backticks, no explanation.

Headlines:
{{ $json.news }}

parameters.jsCode:
const aiRaw = $input.first().json.output || '[]';
const data = $('Process Combined Data').first().json;

// Parse data
let emails = [];
let news = [];
let events = [];
let aiSummaries = [];

try { emails = JSON.parse(data.emails); } catch(e) {}
try { news = JSON.parse(data.news); } catch(e) {}
try { events = JSON.parse(data.events); } catch(e) {}

// Parse AI summaries
try {
  const cleaned = aiRaw.replace(/```json/gi,'').replace(/```/g,'').trim();
  aiSummaries = JSON.parse(cleaned);
} catch(e) {
  aiSummaries = [];
}

// Helper: get summary for a headline
function getSummary(title) {
  const match = aiSummaries.find(s => s.title && title.includes(s.title.substring(0, 20)));
  return match ? match.summary : '';
}

// Greeting based on time with emoji
const hour = new Date().getHours();
let greeting = '';
let emoji = '';

if (hour >= 5 && hour < 12) {
  greeting = 'Good Morning';
  emoji = '☀️';
} else if (hour >= 12 && hour < 18) {
  greeting = 'Good Afternoon';
  emoji = '🌤️';
} else {
  greeting = 'Good Evening';
  emoji = '🌙';
}

// === BUILD EMAIL ROWS ===

// --- Email rows ---
let emailRows = '';
const showEmails = emails.slice(0, 6);
for (let i = 0; i < showEmails.length; i++) {
  const e = showEmails[i];
  const fromName = e.from.split('<')[0].trim() || e.from;
  const fromEmail = (e.from.match(/<(.+?)>/) || ['',''])[1];
  const isLast = i === showEmails.length - 1;
  emailRows += `
  <tr>
    <td style="padding:16px 24px;${!isLast ? ' border-bottom:1px solid #f1f5f9;' : ''}">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
        <td width="44" valign="top">
          <div style="width:40px; height:40px; border-radius:10px; background:${['#6366f1','#ec4899','#f59e0b','#10b981','#8b5cf6','#06b6d4'][i % 6]}; color:#fff; font-size:16px; font-weight:700; line-height:40px; text-align:center;">${fromName.charAt(0).toUpperCase()}</div>
        </td>
        <td style="padding-left:14px;">
          <p style="margin:0 0 2px 0; font-size:14px; font-weight:700; color:#1e293b;">${fromName}</p>
          <p style="margin:0 0 4px 0; font-size:13px; font-weight:600; color:#334155;">${e.subject}</p>
          <p style="margin:0; font-size:12px; color:#94a3b8; line-height:1.4;">${e.snippet}...</p>
        </td>
      </tr></table>
    </td>
  </tr>`;
}
const remainingEmails = emails.length - showEmails.length;
if (remainingEmails > 0) {
  emailRows += `
  <tr><td style="padding:12px 24px; text-align:center;">
    <a href="https://mail.google.com" style="font-size:13px; color:#6366f1; text-decoration:none; font-weight:600;">+${remainingEmails} more emails — Open Gmail →</a>
  </td></tr>`;
}

// --- News rows ---
let newsRows = '';
const showNews = news.slice(0, 6);
for (let i = 0; i < showNews.length; i++) {
  const n = showNews[i];
  const summary = getSummary(n.title);
  const isLast = i === showNews.length - 1;
  const colors = ['#ef4444','#f59e0b','#3b82f6','#10b981','#8b5cf6','#ec4899'];
  newsRows += `
  <tr>
    <td style="padding:14px 24px;${!isLast ? ' border-bottom:1px solid #f1f5f9;' : ''}">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
        <td width="6" valign="top" style="padding-top:6px;"><div style="width:6px; height:6px; border-radius:50%; background:${colors[i % 6]};"></div></td>
        <td style="padding-left:12px;">
          <a href="${n.link}" style="font-size:14px; font-weight:600; color:#1e293b; text-decoration:none; line-height:1.4;">${n.title}</a>
          ${summary ? `<p style="margin:4px 0 0 0; font-size:12px; color:#64748b; line-height:1.4;">${summary}</p>` : ''}
        </td>
      </tr></table>
    </td>
  </tr>`;
}
const remainingNews = news.length - showNews.length;
if (remainingNews > 0) {
  newsRows += `
  <tr><td style="padding:12px 24px; text-align:center;">
    <a href="https://news.google.com" style="font-size:13px; color:#6366f1; text-decoration:none; font-weight:600;">+${remainingNews} more headlines — Open Google News →</a>
  </td></tr>`;
}

// --- Calendar rows ---
let calendarRows = '';
if (events.length === 0) {
  calendarRows = `
  <tr><td style="padding:24px; text-align:center;">
    <p style="margin:0 0 4px 0; font-size:28px;">🎉</p>
    <p style="margin:0 0 4px 0; font-size:15px; font-weight:600; color:#10b981;">No meetings today!</p>
    <p style="margin:0; font-size:13px; color:#94a3b8;">Your calendar is clear — deep work time.</p>
  </td></tr>`;
} else {
  for (let i = 0; i < events.length; i++) {
    const ev = events[i];
    const isLast = i === events.length - 1;
    const timeStr = ev.end ? `${ev.start} – ${ev.end}` : ev.start;
    calendarRows += `
    <tr>
      <td style="padding:14px 24px;${!isLast ? ' border-bottom:1px solid #f1f5f9;' : ''}">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
          <td width="52" valign="top">
            <div style="background:#f0fdf4; border:1px solid #bbf7d0; border-radius:8px; padding:6px 10px; text-align:center;">
              <p style="margin:0; font-size:11px; color:#16a34a; font-weight:700;">${timeStr}</p>
            </div>
          </td>
          <td style="padding-left:14px;">
            <p style="margin:0; font-size:14px; font-weight:600; color:#1e293b;">${ev.title}</p>
            ${ev.location ? `<p style="margin:4px 0 0 0; font-size:12px; color:#94a3b8;">📍 ${ev.location}</p>` : ''}
          </td>
        </tr></table>
      </td>
    </tr>`;
  }
}

// --- Tips ---
const tips = [
  { icon: '🎯', tip: 'Start with your hardest task — willpower is highest in the morning.' },
  { icon: '📵', tip: 'Block 2 hours of distraction-free time. Close Slack & socials.' },
  { icon: '✍️', tip: 'Write down 3 must-do items. Anything else is a bonus.' },
  { icon: '🧘', tip: 'Take a 5-min break every 90 minutes. Your brain needs it.' },
  { icon: '📧', tip: 'Batch email replies at 11 AM and 4 PM. Don\'t live in your inbox.' },
  { icon: '🚀', tip: 'Ship something small today. Progress beats perfection.' },
  { icon: '💧', tip: 'Drink water before coffee. Hydration boosts focus by 14%.' }
];
const todayTip = tips[new Date().getDay() % tips.length];

// === ASSEMBLE FULL HTML ===
const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0; padding:0; background-color:#f1f5f9; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif; -webkit-font-smoothing:antialiased;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:32px 16px;">
<tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background:#ffffff; border-radius:16px; overflow:hidden; box-shadow:0 4px 30px rgba(0,0,0,0.06);">

<!-- HEADER -->
<tr><td style="background:linear-gradient(135deg,#0f172a 0%,#1e293b 100%); padding:36px 32px; text-align:center;">
  <p style="margin:0 0 6px 0; font-size:12px; color:#94a3b8; letter-spacing:3px; text-transform:uppercase; font-weight:500;">${emoji} ${greeting}</p>
  <h1 style="margin:0 0 8px 0; font-size:26px; color:#ffffff; font-weight:700;">Your Daily Digest</h1>
  <p style="margin:0; font-size:13px; color:#64748b;">${data.date}</p>
</td></tr>

<!-- STATS -->
<tr><td style="padding:24px 32px 0 32px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
    <td width="33%" style="padding:0 6px 0 0;">
      <div style="background:#eff6ff; border-radius:12px; padding:18px 12px; text-align:center;">
        <p style="margin:0; font-size:28px; font-weight:800; color:#2563eb;">${data.emailCount}</p>
        <p style="margin:6px 0 0 0; font-size:11px; color:#64748b; letter-spacing:1px; text-transform:uppercase;">Emails</p>
      </div>
    </td>
    <td width="33%" style="padding:0 3px;">
      <div style="background:#fefce8; border-radius:12px; padding:18px 12px; text-align:center;">
        <p style="margin:0; font-size:28px; font-weight:800; color:#ca8a04;">${data.newsCount}</p>
        <p style="margin:6px 0 0 0; font-size:11px; color:#64748b; letter-spacing:1px; text-transform:uppercase;">News</p>
      </div>
    </td>
    <td width="33%" style="padding:0 0 0 6px;">
      <div style="background:#f0fdf4; border-radius:12px; padding:18px 12px; text-align:center;">
        <p style="margin:0; font-size:28px; font-weight:800; color:#16a34a;">${data.eventCount}</p>
        <p style="margin:6px 0 0 0; font-size:11px; color:#64748b; letter-spacing:1px; text-transform:uppercase;">Events</p>
      </div>
    </td>
  </tr></table>
</td></tr>

<!-- EMAILS SECTION -->
<tr><td style="padding:28px 32px 0 32px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e2e8f0; border-radius:12px; overflow:hidden;">
    <tr><td style="background:#f8fafc; padding:14px 24px; border-bottom:1px solid #e2e8f0;">
      <p style="margin:0; font-size:14px; font-weight:700; color:#1e293b;">📧 Unread Emails <span style="background:#2563eb; color:#fff; font-size:11px; padding:2px 8px; border-radius:10px; margin-left:8px;">${data.emailCount}</span></p>
    </td></tr>
    ${emailRows}
  </table>
</td></tr>

<!-- NEWS SECTION -->
<tr><td style="padding:24px 32px 0 32px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e2e8f0; border-radius:12px; overflow:hidden;">
    <tr><td style="background:#f8fafc; padding:14px 24px; border-bottom:1px solid #e2e8f0;">
      <p style="margin:0; font-size:14px; font-weight:700; color:#1e293b;">📰 Top News <span style="background:#ca8a04; color:#fff; font-size:11px; padding:2px 8px; border-radius:10px; margin-left:8px;">${data.newsCount}</span></p>
    </td></tr>
    ${newsRows}
  </table>
</td></tr>

<!-- CALENDAR SECTION -->
<tr><td style="padding:24px 32px 0 32px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e2e8f0; border-radius:12px; overflow:hidden;">
    <tr><td style="background:#f8fafc; padding:14px 24px; border-bottom:1px solid #e2e8f0;">
      <p style="margin:0; font-size:14px; font-weight:700; color:#1e293b;">📅 Today's Calendar <span style="background:#16a34a; color:#fff; font-size:11px; padding:2px 8px; border-radius:10px; margin-left:8px;">${data.eventCount}</span></p>
    </td></tr>
    ${calendarRows}
  </table>
</td></tr>

<!-- DAILY TIP -->
<tr><td style="padding:24px 32px 0 32px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:linear-gradient(135deg,#faf5ff,#ede9fe); border-radius:12px; border:1px solid #e9d5ff;">
    <tr><td style="padding:20px 24px;">
      <p style="margin:0 0 8px 0; font-size:13px; font-weight:700; color:#7c3aed; letter-spacing:1px; text-transform:uppercase;">💡 Daily Tip</p>
      <p style="margin:0; font-size:14px; color:#4c1d95; line-height:1.5;">${todayTip.icon} ${todayTip.tip}</p>
    </td></tr>
  </table>
</td></tr>

<!-- FOOTER -->
<tr><td style="padding:28px 32px; text-align:center;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
    <tr><td style="border-top:1px solid #f1f5f9; padding-top:20px; text-align:center;">
      <p style="margin:0 0 6px 0; font-size:12px; color:#94a3b8;">Generated automatically with AI ✨</p>
      <p style="margin:0; font-size:11px; color:#cbd5e1;">Powered by <a href="https://n8n.io" style="color:#6366f1; text-decoration:none;">n8n</a> · <a href="https://mail.google.com" style="color:#6366f1; text-decoration:none;">Open Gmail</a> · <a href="https://calendar.google.com" style="color:#6366f1; text-decoration:none;">Open Calendar</a></p>
    </td></tr>
  </table>
</td></tr>

</table>
</td></tr></table>
</body></html>`;

return [{ json: { htmlEmail: html, date: data.date, emailCount: data.emailCount, newsCount: data.newsCount, eventCount: data.eventCount } }];
